#!/usr/bin/env python3
from fractions import Fraction
from math import factorial, comb

def H(n,r=1):
    return sum((Fraction(1,k**r) for k in range(1,n+1)),Fraction(0))

def mul(p,q):
    out=[Fraction(0)]*(len(p)+len(q)-1)
    for i,a in enumerate(p):
        for j,b in enumerate(q): out[i+j]+=a*b
    return out

def direct_coeffs(m,k):
    # coefficients of c_k(a) through a^2; return derivatives of order 0,1,2
    p=[Fraction(1)]
    for j in range(k):
        p=mul(p,[Fraction(j-m),Fraction(1)])
        p=mul(p,[Fraction(j-2*m),Fraction(2)])
    p=[x/Fraction(factorial(k)**2) for x in p]
    p += [Fraction(0)]*(3-len(p))
    return p[0],p[1],2*p[2]

def closed(m,k):
    if k<=m:
        C=Fraction(comb(m,k)*comb(2*m,k))
        A=H(m)-H(m-k)
        B=H(2*m)-H(2*m-k)
        A2=H(m,2)-H(m-k,2)
        B2=H(2*m,2)-H(2*m-k,2)
        return C,-C*(A+2*B),C*((A+2*B)**2-(A2+4*B2))
    if k<=2*m:
        r=k-m
        D=Fraction(((-1)**r)*factorial(m)*factorial(2*m)*factorial(r-1),
                   factorial(m-r)*factorial(m+r)**2)
        E=H(r-1)-H(m)-2*(H(2*m)-H(m-r))
        return Fraction(0),D,2*D*E
    s=k-2*m
    J=Fraction(4*((-1)**m)*factorial(m)*factorial(2*m)*
               factorial(m+s-1)*factorial(s-1),
               factorial(2*m+s)**2)
    return Fraction(0),Fraction(0),J

def check(m):
    p=6*m+1
    for k in range(p):
        d=direct_coeffs(m,k); c=closed(m,k)
        assert d==c,(m,k,d,c)
        if k<=m:
            assert c[0]!=0
        elif k<=2*m:
            assert c[0]==0 and c[1]!=0
        else:
            assert c[0]==0 and c[1]==0 and c[2]!=0

    # Aggregate cutoff sums reconstructed in the two independent representations.
    F0=F2T=H1T=Psi=Fraction(0)
    for k in range(p):
        c0,c1,c2=direct_coeffs(m,k); z=Fraction(1,2**k)
        if k<=m:
            F0+=c0*z; Psi+=(12*k+1)*c0*z; H1T+=(12*k+1)*c1*z
        if k<=2*m: F2T+=c2*z

    F0c=F2Tc=H1Tc=Psic=Fraction(0)
    for k in range(m+1):
        c0,c1,c2=closed(m,k); z=Fraction(1,2**k)
        F0c+=c0*z; F2Tc+=c2*z
        Psic+=(12*k+1)*c0*z; H1Tc+=(12*k+1)*c1*z
    for r in range(1,m+1):
        k=m+r; _,_,c2=closed(m,k); F2Tc+=c2*Fraction(1,2**k)
    assert F0==F0c and Psi==Psic and H1T==H1Tc and F2T==F2Tc

def main():
    for m in range(1,18): check(m)
    print({"m_range":[1,17],"failures":[]})

if __name__=="__main__": main()
